"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    flags = {"1": True, "0": False, "": None}
    for number, line in enumerate(lines, start=1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        fields = line.split(",")
        if len(fields) != 3:
            raise ValueError(f"line {number}: expected three fields")
        id_, day, flag = (field.strip() for field in fields)
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {number}: expected an integer day") from exc
        if flag not in flags:
            raise ValueError(f"line {number}: expected 1, 0, or an empty flag")
        out.append({"id": id_, "day": day, "flagged": flags[flag]})
    return out


def dedupe_transcripts(events):
    """Remove duplicate transcripts. See SPEC.md section 5."""
    seen = {e["id"]: e for e in events}
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    counts = [0] * (end_day - start_day + 1)
    for e in events:
        if start_day <= e["day"] <= end_day and e["flagged"] is True:
            counts[e["day"] - start_day] += 1
    return counts
