import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_in_denominator():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_dedupe_keeps_last_input_record_even_if_day_is_earlier():
    old, b, later_day, replacement = parse_transcript_log(["a,4,0", "b,2,1", "c,3,0", "a,2,1"])
    assert dedupe_transcripts([old, b, later_day, replacement]) == [replacement, b, later_day]


def test_parse_skips_comments_and_blank_lines_and_strips_fields():
    lines = ["", "  # ignored", " a , 2 , 0 ", " \t", " b , -1 ,  "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 2, "flagged": False},
        {"id": "b", "day": -1, "flagged": None},
    ]


@pytest.mark.parametrize("line", ["a,1", "a,1,1,0", "a,one,1"])
def test_parse_reports_original_line_number(line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["  ", "ok,1,1", " # comment", line])


def test_daily_counts_and_window_boundaries():
    events = parse_transcript_log(["a,0,1", "b,2,1", "c,2,1", "d,3,", "e,4,1"])
    counts = daily_flag_counts(events, 1, 3)
    assert counts == [0, 2, 0]
    assert daily_flag_counts(events, 3, 1) == []
    assert flags_in_window(counts, 1) == 0
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 5) == 2


def test_summary_weights_transcripts_and_uses_calendar_days():
    groups = {"a": parse_transcript_log(["x,1,1", "y,1,1"]), "b": parse_transcript_log(["z,4,0"]), "c": []}
    assert pooled_flag_rate(groups) == 2 / 3
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary({"a": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_rate_order_and_ranking_ties():
    groups = {"z": [{"flagged": True}], "c": [], "b": [{"flagged": False}], "a": [{"flagged": True}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("c", None), ("z", 1.0)]
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 4) == ["a", "z", "b"]


def test_streak_resets_at_nonpositive_counts():
    assert longest_flag_streak([1, 1, 0, 1, -1, 1]) == 2
    assert longest_flag_streak([]) == 0
